import sys
from bisect import bisect_left

def main():
    data = sys.stdin.read().split()
    n, m = int(data[0]), int(data[1])
    base = [int(x) for x in data[2:2 + n]]
    top = [int(x) for x in data[2 + n:2 + n + m]]
    target = int(data[2 + n + m])
    sums = {0}
    for t in top:
        sums = {s + k * t for s in sums for k in (0, 1, 2)}
    sums = sorted(sums)
    best = None
    for b in base:
        need = target - b
        idx = bisect_left(sums, need)
        for j in (idx - 1, idx):
            if 0 <= j < len(sums):
                cost = b + sums[j]
                key = (abs(cost - target), cost)
                if best is None or key < best:
                    best = key
    print(best[1])

main()

